contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 newLimit) public {
        c.AdjustBetAmounts(newLimit); if (__ESBMC_reverted()) return;
        assert(c.currentBetLimit() == newLimit);
    }
    receive() external payable {}
}

